insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"fca974ff-1293-4766-a503-4ec0d68eb56d","control_id":"C-ITC-012","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure ITC is claimed only after goods or services are received (including deemed receipt in bill-to-ship-to) and on the last lot for multiple-lot supplies.","law_refs":["CGST-ACT-S16-2","CGST-ACT-S155","CGST-RULE-138"],"required_data":["purchase_register","stock_register","eway_bill_register","gstr2b"],"procedure":"1. Compare invoice date, GRN date and ITC claim period for sample invoices and for all high-value invoices.\\n2. Identify invoices booked at period end with GRN in the following period.\\n3. For bill-to-ship-to, verify e-way bills show delivery to the third party on the company''s direction.\\n4. For services, obtain evidence of service rendering (reports, timesheets, deliverables).","automation":null,"expected_result":"ITC claimed in the period of receipt with documentary proof.","exception_conditions":"ITC claimed before GRN; no evidence of service receipt; e-way bill shows delivery elsewhere without direction.","risk_level":"medium","exposure_basis":"Ineligible/excess ITC to be reversed + interest u/s 50(3) @ 18% p.a. only to the extent the credit was utilised (electronic credit ledger balance fell below the wrongly availed amount, Rule 88B); penalty exposure u/s 73/74/74A. Penalty u/s 122 for availing ITC without receipt.","evidence_required":["GRN and e-way bill mapping","Service deliverables","Delivery instructions"],"corrective_action":"Defer/reverse ITC to the period of receipt, link ITC claim to GRN in ERP.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.37238+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"1ca922b8-82c7-432f-9ddc-7f765c9f9b31","control_id":"C-ITC-014","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure permanent and temporary ITC reversals are reported in the correct tables and re-claims do not exceed the reversed balance in ECRRS.","law_refs":["CIRC-170-02-2022","CGST-RULE-86","CGST-RULE-37","CGST-RULE-37A"],"required_data":["gstr3b","ecrrs","electronic_credit_ledger"],"procedure":"1. Extract GSTR-3B Table 4(A), 4(B)(1), 4(B)(2), 4(D)(1) and 4(D)(2) for each month.\\n2. Reconcile temporary reversals (Rule 37, 37A, 16(2)(b)/(c)) to ECRRS opening balance and closing balance.\\n3. Verify re-claims in 4(A)(5)/4(D)(1) are supported by documentation and do not exceed ECRRS balance.\\n4. Check that permanent reversals are not re-claimed.","automation":null,"expected_result":"ECRRS balance equals temporarily reversed ITC pending re-claim; table-wise reporting correct.","exception_conditions":"Re-claim exceeding ECRRS balance; permanent reversals reported in 4(B)(2); opening ECRRS balance not declared.","risk_level":"medium","exposure_basis":"Ineligible/excess ITC to be reversed + interest u/s 50(3) @ 18% p.a. only to the extent the credit was utilised (electronic credit ledger balance fell below the wrongly availed amount, Rule 88B); penalty exposure u/s 73/74/74A.","evidence_required":["Table 4 analysis","ECRRS statement","Re-claim workings"],"corrective_action":"Correct reporting prospectively, reverse unsupported re-claims, and maintain a reversal/re-claim register.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.38176+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"aea68ba2-44d5-4a00-bdda-54f4b995b832","control_id":"C-ITC-015","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Quantify and defend ITC claimed for FY 2017-18 and 2018-19 not reflected in GSTR-2A using the Circular 183/15/2022-GST procedure.","law_refs":["CIRC-183-15-2022","CGST-ACT-S16-2","CGST-ACT-S16-5"],"required_data":["gstr2a","gstr3b","purchase_register"],"procedure":"1. Reconcile purchase register with GSTR-2A (as GSTR-2B did not exist) for FY 2017-18 and 2018-19.\\n2. Classify mismatches: supplier did not file, supplier filed under wrong GSTIN/B2C, filed in later period.\\n3. For each supplier above the Circular threshold, obtain a CA/CMA certificate; below threshold, supplier certificate confirming supply and tax payment.\\n4. Map to any pending notices/orders for these years and limitation status.","automation":{"type": "PR_2B_3B", "engine": "recon"},"expected_result":"All mismatches supported by certificates per Circular 183/15/2022.","exception_conditions":"Certificates not obtained; supplier non-filer; mismatch already confirmed in order.","risk_level":"high","exposure_basis":"Ineligible/excess ITC to be reversed + interest u/s 50(3) @ 18% p.a. only to the extent the credit was utilised (electronic credit ledger balance fell below the wrongly availed amount, Rule 88B); penalty exposure u/s 73/74/74A.","evidence_required":["2A reconciliation","Supplier/CA certificates"],"corrective_action":"Collect certificates, file replies, and pay where unsupported (consider Section 128A waiver eligibility).","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.385083+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"362b1702-a5f9-4607-830e-39b507b06593","control_id":"D-RCM-001","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure tax under reverse charge is discharged on all services notified under Section 9(3).","law_refs":["CGST-ACT-S9-3","NOTIF-13-2017-CTR","CGST-ACT-S31-3-F","CGST-ACT-S13-3"],"required_data":["general_ledger","purchase_register","rcm_statement","gstr3b"],"procedure":"1. Map expense ledgers and vendor categories to notified RCM services: GTA (where supplier has not opted forward charge), advocate/legal fees, director sitting fees and remuneration (non-employee), security services by non-body corporate, sponsorship, renting of motor vehicles by non-body corporate (where conditions apply), insurance agent, recovery agent services.\\n2. Extract total payments/expenses per category per month and recompute RCM liability.\\n3. Compare with RCM paid in GSTR-3B Table 3.1(d) and with self-invoices issued.\\n4. For GTA, verify vendor declarations of forward charge option.\\n5. Confirm ITC on RCM paid availed in Table 4(A)(3).","automation":{"key": "RCM_NOTIFIED", "engine": "check"},"expected_result":"RCM liability paid in cash in the month of time of supply for all notified services.","exception_conditions":"No RCM on director sitting fees or legal fees; GTA under RCM treated as forward charge without declaration; RCM paid late.","risk_level":"high","exposure_basis":"RCM tax payable in cash + interest u/s 50(1) from time of supply; ITC re-available (largely revenue-neutral except interest and blocked/ exempt-use portions).","evidence_required":["RCM ledger mapping","RCM computation","Self-invoices","GTA declarations"],"corrective_action":"Pay RCM with interest through DRC-03 or next GSTR-3B, issue self-invoices, claim ITC in the period of payment, and configure RCM tax codes in vendor master.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.38951+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"12d7dc8d-98b8-42bc-81e1-a9d45c25e5db","control_id":"D-RCM-002","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure IGST is paid on all services received from suppliers located outside India where the place of supply is India.","law_refs":["IGST-ACT-S5-3","IGST-ACT-S2-11","IGST-ACT-S13","NOTIF-10-2017-ITR","CGST-ACT-S13-3"],"required_data":["bank_payments","general_ledger","purchase_register","rcm_statement","gstr3b"],"procedure":"1. Extract foreign currency outward remittances (Form 15CA/CB data, bank SWIFT records) and foreign vendor ledgers.\\n2. Classify each payment: import of goods, import of services, reimbursement, capital transaction.\\n3. Determine place of supply under IGST Section 13 for each service.\\n4. Compare IGST RCM payable with GSTR-3B Table 3.1(d) by month (time of supply per Section 13(3) including associated enterprise rule).\\n5. Verify ITC on RCM paid claimed in Table 4(A)(2).","automation":{"key": "RCM_IMPORT_OF_SERVICES", "engine": "check"},"expected_result":"IGST paid on all imported services in the correct period.","exception_conditions":"Royalty, consultancy, software, marketing, commission paid abroad without RCM; RCM paid on payment date ignoring AE book entry date.","risk_level":"high","exposure_basis":"IGST under RCM + interest u/s 50(1); ITC generally re-available, so exposure is primarily interest and penalty except where ITC restricted.","evidence_required":["Foreign remittance listing","Contracts/invoices","POS analysis","RCM payment challans"],"corrective_action":"Pay IGST with interest, claim ITC, and include GST RCM check in the foreign remittance approval workflow.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.393893+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"e77b23f8-c884-4907-9fdb-1081adf8746a","control_id":"D-RCM-003","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Capture import of services paid through corporate credit cards and employee reimbursements (cloud, SaaS, advertising, subscriptions) for RCM.","law_refs":["IGST-ACT-S5-3","IGST-ACT-S2-11","NOTIF-10-2017-ITR"],"required_data":["bank_payments","general_ledger","journal_vouchers"],"procedure":"1. Extract corporate card statements and employee expense claims with foreign currency transactions.\\n2. Identify foreign vendors (cloud services, design tools, ads platforms, journals, conferences).\\n3. Check whether the vendor issued an invoice with Indian GSTIN (forward charge as OIDAR supplier to registered persons is not applicable; registered recipient pays RCM).\\n4. Recompute IGST RCM and compare with RCM paid.","automation":{"key": "RCM_IMPORT_OF_SERVICES", "engine": "check"},"expected_result":"RCM paid on all foreign digital services received by the registered entity.","exception_conditions":"Card spends on foreign SaaS without RCM; vendor invoices addressed to employees.","risk_level":"medium","exposure_basis":"IGST under RCM + interest u/s 50(1).","evidence_required":["Card statements","Vendor invoices","RCM working"],"corrective_action":"Pay IGST RCM with interest, update vendor invoices to company GSTIN where available, and route subscriptions through AP.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.398372+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"fd314f67-233b-431e-9a4c-3c55a51b11fa","control_id":"D-RCM-004","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["related_party"],"objective":"Ensure cost allocations, management fees, recharges and reimbursements payable to overseas related parties are evaluated as import of services, including transactions without consideration.","law_refs":["CGST-ACT-SCH1-4","IGST-ACT-S5-3","CIRC-210-04-2024","CGST-RULE-28","CGST-ACT-S13-3"],"required_data":["general_ledger","journal_vouchers","bank_payments","receivables_payables"],"procedure":"1. Obtain intercompany agreements, transfer pricing documentation and intercompany ledger entries with overseas group entities.\\n2. Identify cost allocations (IT, HR, insurance, licences, travel) and reimbursements of costs incurred abroad on behalf of the Indian entity.\\n3. Determine whether each is a supply of service by the overseas entity; where no consideration, evaluate Schedule I para 4.\\n4. Apply valuation: invoice value deemed OMV where Indian entity eligible for full ITC (Circular 210/4/2024-GST); otherwise Rule 28.\\n5. Determine time of supply for associated enterprises (earlier of book entry and payment) and compare with RCM paid.","automation":null,"expected_result":"RCM paid on all taxable intercompany services at correct value and time.","exception_conditions":"Recharges booked via journal entries without RCM; time of supply based only on payment; partial-exempt entity adopting nil value.","risk_level":"high","exposure_basis":"IGST RCM + interest u/s 50(1) from book-entry date; ITC restricted where entity has exempt supplies.","evidence_required":["Intercompany agreements","TP study","Recharge invoices / debit notes","RCM workings"],"corrective_action":"Pay RCM with interest, issue self-invoices, align GST with transfer pricing documentation, and set an intercompany RCM review at each book closing.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.402941+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"c53d5ef4-f521-4818-bf7a-28dff4f085f3","control_id":"D-RCM-005","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["related_party"],"objective":"Ensure premiums for D&O liability, global health or life policies taken by the overseas parent and recharged to the Indian entity are assessed for RCM and blocked-credit treatment.","law_refs":["IGST-ACT-S5-3","CGST-ACT-SCH1-4","CGST-ACT-S17-5","CIRC-210-04-2024"],"required_data":["general_ledger","journal_vouchers","bank_payments"],"procedure":"1. Identify global insurance programmes (D&O, global medical, group life) where premium is allocated to the Indian entity.\\n2. Determine the service provider (foreign insurer or parent) and whether a supply is made to the Indian entity.\\n3. Compute RCM on recharged amount (or OMV) and assess ITC: D&O liability cover generally eligible; health/life cover blocked unless obligatory.\\n4. Verify RCM paid and ITC treatment.","automation":null,"expected_result":"RCM discharged on taxable recharges with correct ITC treatment.","exception_conditions":"Global insurance recharge with no RCM; ITC claimed on blocked health/life component.","risk_level":"medium","exposure_basis":"IGST RCM + interest; blocked ITC reversal + interest u/s 50(3) where utilised.","evidence_required":["Global insurance allocation notes","Policy schedules","RCM computation"],"corrective_action":"Pay RCM with interest, reverse blocked ITC, and document allocation basis.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.406563+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"0ea62dfb-4326-4e55-b6dd-fc8bf8449a61","control_id":"D-RCM-006","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Determine the GST treatment of warranty claims paid to dealers, service centres or overseas parties, and of replacement parts supplied under warranty.","law_refs":["CIRC-195-07-2023","IGST-ACT-S13","IGST-ACT-S5-3","CGST-ACT-S15-2"],"required_data":["general_ledger","journal_vouchers","purchase_register","bank_payments"],"procedure":"1. Extract warranty expense and claim ledgers and identify payees (domestic dealers, overseas distributors, service centres, customers).\\n2. For domestic dealers, verify dealer invoices with GST for repair labour/parts and ITC eligibility.\\n3. For overseas parties, determine whether services are performance-based on goods located outside India (place of supply outside India under IGST Section 13(3)) or other services with place of supply in India (RCM).\\n4. For replacement parts supplied free under warranty, apply Circular 195/07/2023-GST (no tax, no ITC reversal for manufacturer); verify extended warranty is taxed separately.\\n5. Check credit notes to customers labelled as warranty for Section 34 eligibility.","automation":null,"expected_result":"Warranty transactions treated per their character, with RCM paid only where place of supply is India.","exception_conditions":"Payments to overseas service providers without POS analysis; ITC reversed unnecessarily on warranty replacements; extended warranty not taxed.","risk_level":"medium","exposure_basis":"IGST RCM + interest where POS in India; potential refund/ITC opportunity where reversal not required.","evidence_required":["Warranty policy and dealer agreements","Claim settlement statements","POS analysis"],"corrective_action":"Pay RCM where applicable, re-avail ITC wrongly reversed (within Section 16(4) limits), and document warranty GST policy.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.410346+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"d536daf0-6471-45bf-9ed9-f11205f4ddcb","control_id":"D-RCM-007","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure reverse charge is paid on notified goods and, where the taxpayer falls within notified classes (e.g., real-estate promoters), on supplies from unregistered persons.","law_refs":["CGST-ACT-S9-3","NOTIF-4-2017-CTR","CGST-ACT-S9-4","CGST-ACT-S12-3","CGST-ACT-S31-3-F"],"required_data":["purchase_register","vendor_master","rcm_statement","gstr3b"],"procedure":"1. Identify purchases of notified RCM goods by HSN from the purchase register.\\n2. Determine whether the taxpayer is a notified class under Section 9(4) and quantify purchases from unregistered suppliers.\\n3. Recompute RCM and compare with Table 3.1(d).\\n4. Verify self-invoices and payment vouchers.","automation":null,"expected_result":"RCM paid on notified goods and applicable unregistered purchases.","exception_conditions":"Notified goods purchased without RCM; promoter shortfall in purchases from registered suppliers not taxed.","risk_level":"medium","exposure_basis":"RCM tax + interest u/s 50(1).","evidence_required":["HSN-wise purchase analysis","Self-invoices"],"corrective_action":"Pay RCM with interest and add HSN-based RCM flags in item master.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.415606+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"9db76d92-a906-40bd-8267-1e7cfde1747a","control_id":"D-RCM-008","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Verify issuance of self-invoices and payment vouchers and correct determination of time of supply for RCM transactions.","law_refs":["CGST-ACT-S31-3-F","CGST-ACT-S13-3","CGST-ACT-S12-3","CIRC-211-05-2024"],"required_data":["rcm_statement","general_ledger","bank_payments"],"procedure":"1. Obtain the self-invoice series and payment vouchers for the period.\\n2. Match RCM transactions with self-invoices and check dates relative to receipt of supply (Rule 47 time limit applies for self-invoices).\\n3. Recompute time of supply (payment date / 60 days from supplier invoice / AE book entry) and compare with RCM payment period.\\n4. Compute interest for delayed RCM payment.","automation":null,"expected_result":"Self-invoice issued for every RCM purchase from unregistered supplier within time; RCM paid in correct period.","exception_conditions":"No self-invoices; RCM paid on annual basis; delayed self-invoicing used to extend Section 16(4) window.","risk_level":"low","exposure_basis":"Interest u/s 50(1) on delayed RCM; penalty u/s 122/125 for non-issuance of documents.","evidence_required":["Self-invoice register","Time-of-supply working"],"corrective_action":"Issue self-invoices contemporaneously, pay interest, and automate RCM document generation.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.419562+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"6d07ea6d-9524-4f97-83f3-a936472961c9","control_id":"D-RCM-009","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Verify RCM liability is discharged only through the electronic cash ledger and that ITC on RCM paid is claimed once in the correct period.","law_refs":["CGST-ACT-S49","CGST-ACT-S16-1","CIRC-170-02-2022"],"required_data":["gstr3b","electronic_cash_ledger","electronic_credit_ledger","rcm_statement"],"procedure":"1. Compare RCM liability in Table 3.1(d) with cash ledger debits for each period.\\n2. Compare RCM ITC claimed in Table 4(A)(2)/(3) with RCM paid and with the portal RCM liability/ITC statement where available.\\n3. Identify RCM ITC claimed without payment or in excess.\\n4. Identify RCM paid but ITC not claimed (opportunity within Section 16(4)).","automation":null,"expected_result":"RCM ITC equals eligible RCM paid in cash.","exception_conditions":"RCM liability set off against ITC; RCM ITC claimed without payment; RCM ITC missed.","risk_level":"high","exposure_basis":"Tax re-payable in cash where set off against credit + interest; ITC over-claim reversal + interest u/s 50(3).","evidence_required":["Cash ledger extract","Table 3.1(d) vs 4(A)(2)/(3) comparison"],"corrective_action":"Pay RCM in cash, reverse unsupported RCM ITC, and claim missed RCM ITC.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.423261+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"2275eb70-d16a-4d8b-a075-9a231675793a","control_id":"D-RCM-010","version":1,"effective_from":"2024-10-10","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure reverse charge is paid on renting of immovable property (other than residential dwelling) by an unregistered person to a registered person, as notified with effect from 10.10.2024.","law_refs":["CGST-ACT-S9-3","NOTIF-13-2017-CTR","CGST-ACT-S31-3-F"],"required_data":["general_ledger","vendor_master","rcm_statement","gstr3b"],"procedure":"1. Extract rent ledgers and landlord master data with GST registration status.\\n2. Identify commercial premises rented from unregistered landlords on or after 10.10.2024.\\n3. Recompute RCM and verify payment and self-invoice.\\n4. Exclude composition-registered landlords only if specifically excluded as per the amended entry; document conclusion.","automation":{"key": "RCM_NOTIFIED", "engine": "check"},"expected_result":"RCM paid on all applicable rent payments from 10.10.2024.","exception_conditions":"Rent from unregistered landlords without RCM.","risk_level":"medium","exposure_basis":"RCM tax + interest u/s 50(1).","evidence_required":["Rent agreements","Landlord registration status","RCM working"],"corrective_action":"Pay RCM with interest and add landlord GST status to lease management.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.426772+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"f6c113d7-6c15-491c-9b26-67bf58b28107","control_id":"D-RCM-011","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["importer"],"objective":"Ensure IGST under RCM is not paid on ocean freight for CIF imports post Mohit Minerals, and that freight arrangements on FOB/EXW terms are evaluated under place-of-supply rules.","law_refs":["JUDG-MOHIT-MINERALS-2022","IGST-ACT-S13","IGST-ACT-S5-3","NOTIF-10-2017-ITR"],"required_data":["bills_of_entry","general_ledger","rcm_statement","bank_payments"],"procedure":"1. Classify imports by Incoterm and identify who contracted the ocean freight.\\n2. For CIF imports, check whether RCM was paid on ocean freight and whether refund was claimed within limitation.\\n3. For FOB/EXW imports where the company contracts with a foreign or Indian freight provider, determine taxability and place of supply.\\n4. Verify GST charged by Indian freight forwarders and ITC eligibility.","automation":null,"expected_result":"No RCM on CIF ocean freight; correct treatment for other freight contracts.","exception_conditions":"RCM continuing on CIF imports; refund not pursued; FOB freight from foreign shipping lines untreated.","risk_level":"low","exposure_basis":"Refund opportunity for RCM wrongly paid (subject to limitation and unjust enrichment); RCM + interest where FOB freight is taxable in India.","evidence_required":["Incoterm-wise import listing","Freight invoices","RCM payments"],"corrective_action":"Stop RCM on CIF freight, file refund where within time, and document freight GST positions.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.430609+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"613b2334-fce4-4483-a31a-4d23c012a74e","control_id":"E-ISD-001","version":1,"effective_from":"2025-04-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["isd","multi_gstin"],"objective":"Ensure that an office receiving invoices for common input services on behalf of distinct persons is registered as ISD from 01.04.2025.","law_refs":["CGST-ACT-S20","CGST-ACT-S24","CGST-RULE-39"],"required_data":["purchase_register","vendor_master","general_ledger"],"procedure":"1. List all GSTINs under the PAN and identify the office (usually HO) receiving invoices for services consumed by multiple units (audit fees, IT, advertisement, insurance, consultancy).\\n2. Verify ISD registration exists in each State where such invoices are received.\\n3. Identify common-service invoices received in a normal GSTIN after 01.04.2025.\\n4. Evaluate exposure where credit retained in a single GSTIN instead of distributed.","automation":null,"expected_result":"ISD registration obtained and common services invoiced to ISD GSTIN.","exception_conditions":"No ISD registration; common invoices booked in normal GSTIN.","risk_level":"high","exposure_basis":"ITC on common services retained in a single GSTIN may be challenged; general penalty exposure under the Act; working capital loss in units.","evidence_required":["ISD registration certificate","Common-service invoice listing"],"corrective_action":"Obtain ISD registration, update vendor billing GSTIN, and distribute credit through GSTR-6.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.434593+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"3c554ecb-0aad-4ff2-b36f-faf84aaa9749","control_id":"E-ISD-002","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["isd"],"objective":"Verify that ISD credit is distributed in the same month, to the correct recipients, on turnover ratio, with matching heads.","law_refs":["CGST-ACT-S20","CGST-RULE-39"],"required_data":["gstr6","gstr2b","sales_register","trial_balance"],"procedure":"1. Download GSTR-6 and ISD-received GSTR-6A/2B for each month.\\n2. Verify all credit received is distributed in the same month.\\n3. Recompute distribution ratio based on turnover of recipient units for the prescribed period.\\n4. Verify head-wise distribution (IGST to other States, CGST/SGST to same State) and ineligible credit distributed as ineligible.","automation":null,"expected_result":"Complete, timely and correctly apportioned distribution.","exception_conditions":"Undistributed balance; distribution to units not using the service; wrong ratio; ineligible credit distributed as eligible.","risk_level":"medium","exposure_basis":"Excess credit distributed recoverable from recipients with interest; under-distribution leads to lost ITC.","evidence_required":["GSTR-6 returns","Turnover ratio working"],"corrective_action":"Issue ISD credit notes/supplementary invoices to correct distribution and standardise distribution keys.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.438783+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"a51d48b0-d679-4785-b5bb-4e6b1aa88c0b","control_id":"E-ISD-003","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["isd","multi_gstin"],"objective":"Ensure ISD credit distributed to recipient units is recorded in their books and availed in GSTR-3B.","law_refs":["CGST-ACT-S20","CGST-RULE-39","CGST-ACT-S16-4"],"required_data":["gstr6","gstr2b","purchase_register","gstr3b"],"procedure":"1. Extract ISD section of each recipient unit''s GSTR-2B.\\n2. Match with ISD invoices booked in the unit''s purchase register/journal.\\n3. Identify unbooked distributions and evaluate time limit for claiming.\\n4. Confirm GSTR-3B Table 4(A)(4) reporting.","automation":null,"expected_result":"All ISD distributions booked and claimed by recipients.","exception_conditions":"ISD credit in 2B not booked; claimed late beyond Section 16(4).","risk_level":"medium","exposure_basis":"Lost ITC (opportunity) if not claimed within time limit.","evidence_required":["ISD 2B extracts","Recipient unit books"],"corrective_action":"Book and claim ISD credit, and add ISD 2B review in unit monthly close.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.442317+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"9fee7ab5-1237-4859-a51e-b5a2b0787774","control_id":"E-ISD-004","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["multi_gstin","isd"],"objective":"Identify vendors invoicing common services to a normal GSTIN where services are consumed by other units, which distorts ITC and may breach ISD requirements.","law_refs":["CGST-ACT-S20","CGST-ACT-S16-1","CIRC-199-11-2023","CGST-ACT-S25-4"],"required_data":["purchase_register","vendor_master","general_ledger"],"procedure":"1. Identify vendors whose services benefit multiple locations (telecom, IT, audit, advertising, security for multiple sites).\\n2. Check billing GSTIN on their invoices vs consuming locations (cost centre mapping).\\n3. Quantify ITC claimed by HO GSTIN for services consumed in other States.\\n4. Evaluate correction: re-billing to ISD or to consuming GSTIN; or cross-charge.","automation":null,"expected_result":"Common services billed to ISD; location-specific services billed to the consuming unit.","exception_conditions":"Out-of-State site services billed to HO GSTIN; common services not distributed.","risk_level":"medium","exposure_basis":"ITC claimed by non-recipient GSTIN may be disallowed + interest u/s 50(3) where utilised.","evidence_required":["Vendor billing analysis","Cost centre consumption"],"corrective_action":"Instruct vendors to bill ISD/consuming unit, cross-charge where appropriate, and update vendor master billing GSTIN.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.445995+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"0772997c-c8f0-4224-b1bd-9453829a84f1","control_id":"E-ISD-005","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["multi_gstin"],"objective":"Ensure supplies of services by HO to branches (distinct persons) are identified, valued and taxed or properly concluded upon.","law_refs":["CGST-ACT-SCH1-2","CGST-RULE-28","CIRC-199-11-2023"],"required_data":["general_ledger","sales_register","trial_balance","journal_vouchers"],"procedure":"1. Identify HO functions supporting branches (management, finance, HR, IT, procurement).\\n2. Review cross-charge invoices issued and valuation methodology.\\n3. Where branches are eligible for full ITC, document adoption of invoice value as OMV per Circular 199/11/2023; where branches make exempt supplies, compute cost-based value under Rule 28 (salary costs need not be included as clarified).\\n4. Verify reporting of cross-charge invoices in GSTR-1 and ITC in branches.","automation":null,"expected_result":"Documented cross-charge policy consistent with Circular 199/11/2023.","exception_conditions":"No cross-charge where branches have exempt supplies; cross-charge invoices not reported.","risk_level":"medium","exposure_basis":"Short-paid output tax + interest u/s 50(1) @ 18% p.a. from the due date of the GSTR-3B of the original period to date of payment; penalty u/s 73/74 (periods up to FY 2023-24) or u/s 74A (FY 2024-25 onwards) if raised in proceedings.","evidence_required":["Cross-charge policy","Invoices and computations"],"corrective_action":"Adopt and document a cross-charge policy and pay tax with interest where branches are not fully eligible.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.449413+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"e4b29bd8-7fdf-4132-9661-9e702cb5313b","control_id":"E-ISD-006","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["multi_gstin"],"objective":"Evaluate GST treatment of employees of one GSTIN working for another (secondment, shared services) including salary recharges.","law_refs":["CGST-ACT-SCH1-2","CIRC-199-11-2023","CGST-RULE-28"],"required_data":["general_ledger","journal_vouchers","trial_balance"],"procedure":"1. Identify salary cost recharges between units from payroll cost-centre allocations and journals.\\n2. Determine whether recharge reflects supply of services by distinct person.\\n3. Apply Circular 199/11/2023 for valuation and recipient ITC eligibility.\\n4. Verify invoicing and GSTR-1 reporting where taxed.","automation":null,"expected_result":"Salary recharges evaluated and taxed or documented.","exception_conditions":"Salary recharges via journals with no GST analysis.","risk_level":"low","exposure_basis":"Short-paid output tax + interest u/s 50(1) @ 18% p.a. from the due date of the GSTR-3B of the original period to date of payment; penalty u/s 73/74 (periods up to FY 2023-24) or u/s 74A (FY 2024-25 onwards) if raised in proceedings.","evidence_required":["Payroll allocations","Recharge journals"],"corrective_action":"Document position and invoice where required.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.452448+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"9d816ec3-011d-4ee6-bd60-0b069426af19","control_id":"F-EINV-001","version":1,"effective_from":"2020-10-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure every IRN generated is recorded in books and auto-populated in GSTR-1, and that cancelled IRNs are not reported.","law_refs":["CGST-RULE-48-4","CGST-ACT-S37"],"required_data":["einvoice_register","gstr1","sales_register"],"procedure":"1. Download IRN register from IRP/e-invoice portal (active and cancelled).\\n2. Match IRNs with sales register (document number, date, value, GSTIN).\\n3. Match IRNs with GSTR-1 auto-populated data and identify overwritten/edited records.\\n4. Classify: IRN active not in books, in books without IRN, cancelled IRN in books/GSTR-1, value mismatch.","automation":{"type": "EINV_GSTR1_BOOKS", "engine": "recon"},"expected_result":"Three-way match with no unexplained items.","exception_conditions":"IRN generated but invoice not booked or not in GSTR-1; cancelled IRN still in books; GSTR-1 record edited post auto-population.","risk_level":"high","exposure_basis":"Short-paid output tax + interest u/s 50(1) @ 18% p.a. from the due date of the GSTR-3B of the original period to date of payment; penalty u/s 73/74 (periods up to FY 2023-24) or u/s 74A (FY 2024-25 onwards) if raised in proceedings.","evidence_required":["IRN register","Three-way reconciliation"],"corrective_action":"Book or cancel orphan IRNs, correct GSTR-1, and pay tax with interest on unreported active IRNs.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.455885+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"2891d7af-6ea8-4aee-99be-1210b2486113","control_id":"F-EINV-002","version":1,"effective_from":"2020-10-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Identify documents required to be e-invoiced that were issued without IRN, which are not valid invoices under Rule 48(5).","law_refs":["CGST-RULE-48-4","NOTIF-EINV-THRESHOLD","CGST-ACT-S122"],"required_data":["sales_register","einvoice_register","customer_master"],"procedure":"1. Confirm e-invoice applicability based on AATO of any FY from 2017-18 onwards.\\n2. Filter sales register for B2B, SEZ, export and B2B credit/debit note documents.\\n3. Match to IRN register; list documents without IRN.\\n4. Check for exempt categories (e.g., exempt supplies, RCM-only documents).","automation":{"key": "EINV_MISSING_IRN", "engine": "check"},"expected_result":"All in-scope documents carry valid IRN and QR code.","exception_conditions":"B2B invoices without IRN; credit notes without IRN; manual invoices from branches.","risk_level":"high","exposure_basis":"Invoice not valid → customer ITC denial and commercial claims; penalty u/s 122; detention risk in transit (s.129).","evidence_required":["Missing IRN report","Applicability workings"],"corrective_action":"Generate IRN where permissible within time limits, else cancel and re-issue; block invoice printing without IRN in ERP.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.459439+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"b6c00718-d18c-4e09-98d6-8c6d501522bb","control_id":"F-EINV-003","version":1,"effective_from":"2020-10-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Detect active IRNs not reported in GSTR-1 (e.g., auto-population failures, deletions) and resulting liability shortfalls.","law_refs":["CGST-RULE-48-4","CGST-ACT-S37","CGST-RULE-88C"],"required_data":["einvoice_register","gstr1","gstr3b"],"procedure":"1. Compare active IRN list for each month with GSTR-1 B2B/EXP/SEZ and CDNR tables.\\n2. Identify records deleted from GSTR-1 auto-draft before filing.\\n3. Assess liability impact and DRC-01B risk.","automation":{"type": "EINV_GSTR1_BOOKS", "engine": "recon"},"expected_result":"All active IRNs reported in GSTR-1 of the correct period.","exception_conditions":"Active IRNs deleted from GSTR-1; IRNs generated for a different GSTIN.","risk_level":"high","exposure_basis":"Short-paid output tax + interest u/s 50(1) @ 18% p.a. from the due date of the GSTR-3B of the original period to date of payment; penalty u/s 73/74 (periods up to FY 2023-24) or u/s 74A (FY 2024-25 onwards) if raised in proceedings.","evidence_required":["IRN vs GSTR-1 exceptions"],"corrective_action":"Report missing IRNs and pay tax with interest; restrict deletion rights in GSTR-1 preparation.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.463405+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"8666ebcf-c374-4817-962a-337033b3624e","control_id":"F-EINV-006","version":1,"effective_from":"2020-10-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Verify e-invoice supply type codes (B2B, SEZWP, SEZWOP, EXPWP, EXPWOP, DEXP), reverse charge flag, POS and HSN accuracy.","law_refs":["CGST-RULE-48-4","IGST-ACT-S16","CGST-RULE-96A"],"required_data":["einvoice_register","sales_register","lut"],"procedure":"1. Extract e-invoice JSON fields for supply type, POS, port code, shipping bill and HSN.\\n2. Compare supply type with nature of supply in books (with/without payment of tax).\\n3. Verify LUT-based supplies are coded WOP and taxed supplies WP.\\n4. Check HSN in e-invoice vs item master.","automation":null,"expected_result":"Consistent supply type and tax treatment across e-invoice, books and GSTR-1.","exception_conditions":"Export under LUT coded EXPWP; SEZ supplies coded B2B; wrong POS.","risk_level":"low","exposure_basis":"Refund rejection and table mismatches; potential output tax on mis-coded supplies.","evidence_required":["E-invoice field extract"],"corrective_action":"Correct mapping in ERP e-invoice integration.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.478405+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"4e972a36-d235-4bbe-ad01-26bcc22afa32","control_id":"G-EWB-001","version":1,"effective_from":"2018-04-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Reconcile e-way bills generated against outward invoices to detect unreported supplies, value mismatches and EWBs without invoices.","law_refs":["CGST-RULE-138","CGST-ACT-S35","CGST-ACT-S37"],"required_data":["eway_bill_register","sales_register","gstr1"],"procedure":"1. Download outward e-way bills (generated by the company and by transporters on its GSTIN) for the period.\\n2. Match EWB document number/date/value/GSTIN with sales register and stock transfer invoices.\\n3. Classify: EWB without invoice in books, invoice above threshold without EWB, value/HSN/quantity mismatch, GSTIN mismatch.\\n4. Investigate EWBs without corresponding sales (potential unrecorded supplies).","automation":{"type": "EWB_SALES", "engine": "recon"},"expected_result":"Every active EWB maps to a booked document with consistent value and recipient.","exception_conditions":"Active EWBs with no invoice in books; taxable value in EWB higher than invoice; recipient GSTIN differs.","risk_level":"high","exposure_basis":"Short-paid output tax + interest u/s 50(1) @ 18% p.a. from the due date of the GSTR-3B of the original period to date of payment; penalty u/s 73/74 (periods up to FY 2023-24) or u/s 74A (FY 2024-25 onwards) if raised in proceedings. Unreconciled active EWBs are a common basis for demand in scrutiny.","evidence_required":["EWB vs sales reconciliation","EWB register download"],"corrective_action":"Account for unrecorded supplies with tax and interest, cancel erroneous EWBs within time, and integrate EWB generation with the invoicing system.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.48298+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"d9f4c982-2236-43b5-be58-a87bdd42c7f3","control_id":"G-EWB-002","version":1,"effective_from":"2018-04-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Identify outward and inward movements exceeding the Rs 50,000 consignment value threshold without an e-way bill.","law_refs":["CGST-RULE-138","CGST-RULE-138A","CGST-ACT-S129","CGST-ACT-S122"],"required_data":["sales_register","eway_bill_register","stock_register"],"procedure":"1. Filter goods invoices, stock transfers and delivery challans with consignment value (including tax) above Rs 50,000 (or lower State threshold for intra-State where applicable).\\n2. Exclude exempt goods/movements under Rule 138(14) and non-motorised conveyance cases with documentation.\\n3. Match with EWB register; list documents without EWB.\\n4. Review transporter-generated EWBs before concluding exception.","automation":{"key": "EWB_MISSING", "engine": "check"},"expected_result":"EWB available for every movement exceeding threshold.","exception_conditions":"Stock transfers and job work dispatches without EWB; customer pickups without EWB.","risk_level":"high","exposure_basis":"Detention/penalty u/s 129 (200% of tax payable for taxable goods where owner comes forward, as amended w.e.f. 01.01.2022) on interception; penalty u/s 122 for transport without documents; reputational and supply-chain disruption.","evidence_required":["Missing EWB report","Exemption analysis"],"corrective_action":"Implement hard stop on dispatch without EWB, train logistics on Rule 138(14) exemptions.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.486704+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"fee2d5e2-5458-4deb-9f02-71c5962a86bb","control_id":"G-EWB-003","version":1,"effective_from":"2018-04-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Detect e-way bills where GST amounts are captured in the cess field (or vice versa), causing mismatches with invoices and returns.","law_refs":["CGST-RULE-138","CGST-RULE-138A"],"required_data":["eway_bill_register","sales_register"],"procedure":"1. Extract EWB tax fields (CGST, SGST, IGST, cess, cess non-advol).\\n2. Flag EWBs where cess is non-zero for HSNs not attracting cess, or where cess equals the expected GST and GST fields are zero.\\n3. Compare with invoice tax breakup.\\n4. Identify the source (manual entry, integration mapping).","automation":{"key": "EWB_TAX_IN_CESS", "engine": "check"},"expected_result":"EWB tax fields mirror invoice tax heads.","exception_conditions":"GST captured as cess; IGST captured in CGST/SGST fields.","risk_level":"low","exposure_basis":"Mismatch-driven scrutiny and transit detention risk on document discrepancies (generally minor penalty if no evasion intent).","evidence_required":["EWB field-level exception list"],"corrective_action":"Fix integration mapping and update EWB within allowed window or cancel and regenerate.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.491789+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"0f92c35c-1737-4e89-b4d0-d5fee3b444d1","control_id":"G-EWB-004","version":1,"effective_from":"2018-04-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Identify EWBs cancelled within 24 hours or rejected by recipient while the related invoice remains in books and goods moved.","law_refs":["CGST-RULE-138","CGST-ACT-S129"],"required_data":["eway_bill_register","sales_register","gstr1"],"procedure":"1. Extract cancelled and rejected EWBs with reasons.\\n2. Match document numbers with sales register and GSTR-1.\\n3. Where invoice remains active, verify whether a replacement EWB was generated for the movement.\\n4. Investigate patterns of repeated cancellation for the same customer/vehicle.","automation":{"key": "EWB_CANCELLED_DISCARDED", "engine": "check"},"expected_result":"Cancelled EWBs relate to cancelled supplies or replaced by valid EWB.","exception_conditions":"Invoice booked but EWB cancelled with no replacement; frequent cancellations post movement.","risk_level":"medium","exposure_basis":"Detention/penalty u/s 129 (200% of tax payable for taxable goods where owner comes forward, as amended w.e.f. 01.01.2022) on interception; penalty u/s 122 for transport without documents; reputational and supply-chain disruption.","evidence_required":["Cancelled EWB analysis"],"corrective_action":"Generate valid EWB process controls and investigate anomalies; document reasons for cancellations.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.495564+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"971929d0-ee92-488c-9498-17f207963ae7","control_id":"G-EWB-005","version":1,"effective_from":"2018-04-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure dispatch-from addresses on EWBs are registered places of business of the GSTIN and that bill-from GSTIN corresponds to the State of dispatch.","law_refs":["CGST-RULE-138","CGST-ACT-S25","CGST-RULE-19"],"required_data":["eway_bill_register","stock_register"],"procedure":"1. Extract dispatch-from PIN code and address from EWBs.\\n2. Compare with registered principal and additional places of business.\\n3. Identify dispatches from third-party warehouses or other State locations under a different GSTIN.\\n4. For bill-from-dispatch-from transactions (Type 3/4), verify supporting documents.","automation":null,"expected_result":"All dispatch locations registered and consistent with bill-from GSTIN.","exception_conditions":"Goods dispatched from unregistered warehouses; dispatch State differs from GSTIN State without valid bill-from-dispatch-from structure.","risk_level":"medium","exposure_basis":"Detention/penalty u/s 129 (200% of tax payable for taxable goods where owner comes forward, as amended w.e.f. 01.01.2022) on interception; penalty u/s 122 for transport without documents; reputational and supply-chain disruption. Also registration non-compliance (see A-REG-001).","evidence_required":["Dispatch location analysis"],"corrective_action":"Register locations, correct EWB templates, and validate dispatch PIN in ERP.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.498813+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"2c805e6d-64a0-4901-ae5d-124d83dc577e","control_id":"G-EWB-006","version":1,"effective_from":"2018-04-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Use inward EWBs as evidence of receipt and to detect purchases not booked or EWBs raised on the company without supply.","law_refs":["CGST-RULE-138","CGST-ACT-S16-2"],"required_data":["eway_bill_register","purchase_register","gstr2b"],"procedure":"1. Download EWBs generated by others where the company is recipient.\\n2. Match with purchase register and GRNs.\\n3. List inward EWBs without purchase booking and invoices without EWBs where required.\\n4. Reject EWBs not relating to the company within 72 hours going forward.","automation":null,"expected_result":"Inward EWBs reconcile to purchases.","exception_conditions":"Inward EWBs unrelated to genuine purchases (misuse of GSTIN); purchases without EWB.","risk_level":"medium","exposure_basis":"Potential ITC challenge where receipt cannot be evidenced; misuse of GSTIN by third parties.","evidence_required":["Inward EWB reconciliation"],"corrective_action":"Reject unrelated EWBs, follow up vendors, and investigate GSTIN misuse.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.503221+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"3d7946fa-13af-4ac4-8ce7-6e7e0bc98ff3","control_id":"G-EWB-007","version":1,"effective_from":"2018-04-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["job_work","multi_gstin"],"objective":"Ensure movements other than sales (job work, branch transfer, FOC, sale-on-approval, returns) are covered by delivery challans and EWBs.","law_refs":["CGST-RULE-55","CGST-RULE-138","CGST-ACT-S143"],"required_data":["eway_bill_register","stock_register","itc04"],"procedure":"1. Extract non-sale stock movements from the stock register.\\n2. Verify delivery challans issued with prescribed particulars.\\n3. Verify EWB generated where required (job work inter-State movements require EWB irrespective of value).\\n4. Match job work challans with ITC-04.","automation":{"key": "EWB_MISSING", "engine": "check"},"expected_result":"All non-sale movements documented with challans and EWBs.","exception_conditions":"Job work dispatches without EWB; returns from customers without documents.","risk_level":"medium","exposure_basis":"Detention/penalty u/s 129 (200% of tax payable for taxable goods where owner comes forward, as amended w.e.f. 01.01.2022) on interception; penalty u/s 122 for transport without documents; reputational and supply-chain disruption.","evidence_required":["Non-sale movement listing","Challans and EWBs"],"corrective_action":"Generate challan/EWB through ERP for all movement types.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.506855+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"a94dae19-978e-4de5-a2a7-bd9eb7fcfd92","control_id":"G-EWB-008","version":1,"effective_from":"2018-04-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure Part-B (vehicle details) is updated and goods reach before EWB validity expires or validity is extended.","law_refs":["CGST-RULE-138","CGST-ACT-S129"],"required_data":["eway_bill_register"],"procedure":"1. Extract EWBs with Part-B missing or vehicle updates.\\n2. Compare validity end with actual delivery/GRN date of customer where available.\\n3. Identify expired EWBs without extension where goods were in transit.","automation":null,"expected_result":"Part-B updated before movement; validity sufficient or extended.","exception_conditions":"Part-A only EWBs used for movement; expired EWBs.","risk_level":"low","exposure_basis":"Detention/penalty u/s 129 (200% of tax payable for taxable goods where owner comes forward, as amended w.e.f. 01.01.2022) on interception; penalty u/s 122 for transport without documents; reputational and supply-chain disruption.","evidence_required":["EWB validity analysis"],"corrective_action":"Train transporters and monitor validity via alerts.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.511645+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"3081dbe0-d9b0-401c-9ded-a307687d7e35","control_id":"G-EWB-009","version":1,"effective_from":"2018-04-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["exporter","importer","sez_supplier"],"objective":"Ensure EWBs are generated for movement to port/ICD for exports, to SEZ units, and from port/CFS to premises for imports, with correct transaction type.","law_refs":["CGST-RULE-138","CGST-RULE-138A","CUSTOMS-ACT-S46"],"required_data":["eway_bill_register","shipping_bills","bills_of_entry","sales_register"],"procedure":"1. Map exports to EWBs showing ship-to as port and bill-to as foreign buyer (URP, State 96/Other Country).\\n2. Map imports (BOE) to EWBs for movement from port to place of business.\\n3. Map SEZ supplies to EWBs.","automation":null,"expected_result":"EWBs exist for export, SEZ and import movements.","exception_conditions":"Import consignments moved from port without EWB; export EWB with incorrect ship-to.","risk_level":"medium","exposure_basis":"Detention/penalty u/s 129 (200% of tax payable for taxable goods where owner comes forward, as amended w.e.f. 01.01.2022) on interception; penalty u/s 122 for transport without documents; reputational and supply-chain disruption.","evidence_required":["Export/import EWB mapping"],"corrective_action":"Align logistics SOP for EWB on import/export legs.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.514741+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"4370d1c6-73e5-4fd3-81cc-afbbd0782ccb","control_id":"G-EWB-010","version":1,"effective_from":"2018-04-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Verify EWB HSN, taxable value and quantity are consistent with the invoice, as mismatches result in detention and demands.","law_refs":["CGST-RULE-138","CGST-RULE-46"],"required_data":["eway_bill_register","sales_register","einvoice_register"],"procedure":"1. Match EWB lines with invoice lines on HSN and quantity.\\n2. Flag HSN mismatches and value variances beyond tolerance.\\n3. For e-invoiced documents, ensure EWB generated from IRN to avoid re-keying.","automation":{"type": "EWB_SALES", "engine": "recon"},"expected_result":"EWB and invoice data consistent.","exception_conditions":"Different HSN on EWB vs invoice; quantity/value mismatch.","risk_level":"low","exposure_basis":"Detention/penalty u/s 129 (200% of tax payable for taxable goods where owner comes forward, as amended w.e.f. 01.01.2022) on interception; penalty u/s 122 for transport without documents; reputational and supply-chain disruption.","evidence_required":["Line-level mismatch report"],"corrective_action":"Generate EWB from IRN/ERP integration rather than manual entry.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.517882+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"3b8d6a3c-5b8a-46ce-9963-3dee95234c44","control_id":"H-EXP-001","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["exporter"],"objective":"Reconcile export invoices in books with shipping bills on ICEGATE and Table 6A of GSTR-1 for value, date, port code and SB number.","law_refs":["CGST-RULE-96","CUSTOMS-ACT-S50","IGST-ACT-S16","ADV-EXPORT-ICEGATE"],"required_data":["sales_register","shipping_bills","gstr1","einvoice_register"],"procedure":"1. Extract export invoices from sales register and GSTR-1 Table 6A.\\n2. Download shipping bill data from ICEGATE (SB number, date, port code, invoice number, FOB, IGST).\\n3. Match invoice number, SB details, and values; recompute FOB vs invoice value variances and exchange rates.\\n4. Classify: no SB, SB not in 6A, value mismatch, IGST mismatch, SB date before invoice date.","automation":{"type": "IMPORT_EXPORT", "engine": "recon"},"expected_result":"Complete three-way match supporting export status and refunds.","exception_conditions":"Invoices without SB; Table 6A without SB/port code; IGST in 6A differs from SB.","risk_level":"high","exposure_basis":"Where export not evidenced: IGST on supply + interest (s.50(1)) or LUT condition breach (Rule 96A); stuck IGST refunds (working capital).","evidence_required":["Export reconciliation","ICEGATE SB data","GSTR-1 Table 6A"],"corrective_action":"Update 6A through Table 9A amendment, correct SB via Section 149 where allowed, and pursue refunds.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.521921+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"55ff6c7f-d992-474a-861d-f6065999de66","control_id":"H-EXP-002","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["exporter"],"objective":"Detect export invoices in GSTR-1 Table 6A lacking SB number, SB date or port code.","law_refs":["CGST-RULE-96","CGST-ACT-S37","ADV-EXPORT-ICEGATE"],"required_data":["gstr1","shipping_bills","sales_register"],"procedure":"1. Filter Table 6A records with blank SB number/date/port code.\\n2. Locate the shipping bills and update details through amendment.\\n3. For exports with payment of IGST, verify refund status after correction.","automation":{"key": "EXPORT_SB_MISSING", "engine": "check"},"expected_result":"All 6A records include SB details.","exception_conditions":"Blank SB details; port code invalid.","risk_level":"medium","exposure_basis":"IGST refund not processed; LUT export not evidenced.","evidence_required":["6A exception list"],"corrective_action":"Amend through Table 9A and include SB capture in post-shipment process.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.526651+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"4238c869-4c9e-4fc8-a991-ddc1e4af4eba","control_id":"H-EXP-003","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["exporter"],"objective":"Identify shipping bills where IGST refund has not been processed due to transmission or validation errors and resolve them.","law_refs":["CGST-RULE-96","ADV-EXPORT-ICEGATE","CGST-ACT-S54"],"required_data":["shipping_bills","gstr1","gstr3b","refunds"],"procedure":"1. Download ICEGATE IGST refund status for all SBs with payment of IGST.\\n2. Classify pending items by error type (invoice mismatch, EGM not filed, GSTR-3B IGST short, bank account not validated, record not transmitted).\\n3. Verify GSTR-3B Table 3.1(b) IGST paid covers export IGST in 6A.\\n4. Track resolution actions and ageing.","automation":null,"expected_result":"All IGST refunds processed or errors resolved promptly.","exception_conditions":"Refunds pending due to unresolved errors; transmission failures for whole periods.","risk_level":"medium","exposure_basis":"Blocked IGST refund (working capital); potential loss if limitation issues arise.","evidence_required":["ICEGATE refund status report","Error correspondence"],"corrective_action":"Correct mismatches, file EGM corrections via shipping line, and approach customs refund cell with documents.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.530113+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"2e44c864-5fba-4ff1-8491-f3ac63834e2f","control_id":"H-EXP-004","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["exporter","sez_supplier"],"objective":"Ensure a valid LUT is in force for the financial year before exports/SEZ supplies without payment of IGST, and its ARN is referenced correctly.","law_refs":["CGST-RULE-96A","IGST-ACT-S16"],"required_data":["lut","sales_register","einvoice_register"],"procedure":"1. Obtain LUT acknowledgement (RFD-11) for each financial year and GSTIN.\\n2. Compare LUT filing date with the date of first zero-rated supply without tax.\\n3. Check invoices bear the declaration and correct LUT ARN.\\n4. Identify supplies made before LUT filing or under an expired LUT.","automation":null,"expected_result":"Valid LUT for all zero-rated supplies without tax, correctly referenced.","exception_conditions":"LUT filed late; wrong ARN on invoices; LUT absent for one GSTIN.","risk_level":"medium","exposure_basis":"Exports without valid LUT may be treated as requiring IGST payment + interest; condonation of procedural lapse often possible but uncertain.","evidence_required":["LUT acknowledgements","Invoice samples"],"corrective_action":"File LUT at start of FY, correct ARN references, and document substantive compliance for delayed LUT.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.533648+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"8e462504-8af8-40ef-9fce-a56ffa5c637e","control_id":"H-EXP-005","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["exporter"],"objective":"Ensure goods supplied under LUT are exported within three months of invoice date (or extended period), else IGST with interest is paid.","law_refs":["CGST-RULE-96A","IGST-ACT-S16","CGST-ACT-S50-1"],"required_data":["sales_register","shipping_bills","lut"],"procedure":"1. Compute days between export invoice date and shipping bill/let export date.\\n2. Flag cases exceeding three months without extension.\\n3. Check whether IGST with interest was paid for flagged cases.\\n4. Identify invoices with no SB at all beyond three months.","automation":{"key": "EXPORT_96A_3M", "engine": "check"},"expected_result":"All LUT exports shipped within three months.","exception_conditions":"Invoices raised in advance of shipment by more than three months; unshipped invoices.","risk_level":"high","exposure_basis":"IGST on invoice value + interest u/s 50(1) from invoice date; refundable later on export but interest cost remains.","evidence_required":["Invoice-to-SB ageing"],"corrective_action":"Pay IGST with interest for defaulted cases and claim refund on subsequent export; align invoicing with shipment date.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.538787+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"f675178e-260f-44d0-b38c-8636ed95b657","control_id":"H-EXP-006","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["exporter"],"objective":"Verify that services treated as export meet all five conditions of IGST Section 2(6) and are not intermediary services or supplies to own establishments.","law_refs":["IGST-ACT-S2-6","IGST-ACT-S13","CGST-RULE-96A"],"required_data":["sales_register","customer_master","bank_payments","receivables_payables"],"procedure":"1. List export of service invoices and customer agreements.\\n2. Determine place of supply under IGST Section 13 (default, performance-based, intermediary, etc.).\\n3. Verify foreign exchange realisation (FIRC/e-BRC) within one year under LUT.\\n4. Evaluate intermediary characterisation (arranging/facilitating supplies between others) and supply to establishments of the same entity outside India.\\n5. Check for services performed on goods temporarily imported (performance-based).","automation":null,"expected_result":"All export of services satisfy Section 2(6) and POS outside India.","exception_conditions":"Intermediary arrangements treated as exports; realisation in INR without RBI permission; customer is own branch abroad.","risk_level":"high","exposure_basis":"IGST on invoice value + interest u/s 50(1); refund recoveries.","evidence_required":["Contracts","POS analysis","FIRC/e-BRC"],"corrective_action":"Pay IGST where conditions fail, restructure contracts, and document POS analysis.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.542249+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"19ccee32-5901-4f31-91f8-a98c81981f88","control_id":"H-EXP-007","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["exporter"],"objective":"Verify eligibility for the IGST-paid export route and compliance with associated restrictions, including Rule 96(10) for the period it was in force.","law_refs":["CGST-RULE-96","IGST-ACT-S16","CGST-ACT-S54"],"required_data":["shipping_bills","refunds","bills_of_entry","gstr3b"],"procedure":"1. Identify exports with payment of IGST and refunds received.\\n2. Check whether inputs were procured under concessional schemes (Advance Authorisation, EOU, deemed export) that restricted IGST refund under Rule 96(10) during its operation (it was omitted by notification in October 2024).\\n3. Verify refund received matches IGST paid and was not double-claimed via LUT ITC refund route.","automation":null,"expected_result":"IGST refunds claimed only where eligible.","exception_conditions":"IGST refund with concessional-input procurement during restricted period; double refund.","risk_level":"medium","exposure_basis":"Recovery of refund + interest; penalty.","evidence_required":["Refund statements","Input procurement analysis"],"corrective_action":"Evaluate repayment with interest or contest, considering judicial developments and omission of Rule 96(10).","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.54582+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"bbe937a5-3961-44aa-8821-b6c4a08b1e3a","control_id":"H-EXP-008","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["exporter","sez_supplier"],"objective":"Verify RFD-01 claims for zero-rated supplies without tax are computed under Rule 89(4), filed within two years, and supported.","law_refs":["CGST-ACT-S54","CGST-RULE-89","IGST-ACT-S16"],"required_data":["refunds","gstr3b","gstr2b","shipping_bills","sales_register"],"procedure":"1. Obtain all refund applications, deficiency memos and orders (RFD-01 to RFD-06).\\n2. Recompute net ITC and zero-rated turnover (including the value-cap for goods per Rule 89(4)).\\n3. Check relevant dates and two-year limitation for unfiled periods.\\n4. Verify ITC used in computation is supported by GSTR-2B.","automation":null,"expected_result":"Refunds claimed fully and on time; computations correct.","exception_conditions":"Unclaimed refund periods near limitation; ineligible ITC included; turnover definitions inconsistent.","risk_level":"medium","exposure_basis":"Lost refund (time-barred); recovery of excess refund + interest.","evidence_required":["Refund files","Rule 89(4) recomputation"],"corrective_action":"File pending claims, correct computation, and track limitation dates.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.549145+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"0a4f57dd-3d51-473f-930a-d3152091cc12","control_id":"H-EXP-009","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["exporter"],"objective":"Identify export receivables not realised within prescribed time, with consequences for export of services status, LUT conditions and refunds.","law_refs":["IGST-ACT-S2-6","CGST-RULE-96A","CGST-ACT-S54"],"required_data":["receivables_payables","sales_register","bank_payments"],"procedure":"1. Obtain export receivables ageing with e-BRC/FIRC status.\\n2. Flag service exports outstanding beyond one year (or extended period) under LUT.\\n3. Flag goods exports with refunds where realisation is pending beyond RBI timelines.\\n4. Check write-offs and RBI approvals.","automation":null,"expected_result":"Export proceeds realised within prescribed periods.","exception_conditions":"Old unrealised receivables; write-offs without RBI approval.","risk_level":"medium","exposure_basis":"IGST with interest on service exports where realisation fails; refund recovery for goods exports.","evidence_required":["Receivables ageing","e-BRC data"],"corrective_action":"Pursue realisation or pay tax with interest; obtain RBI extension/write-off approvals.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.554103+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"eacb4228-db84-47f1-b714-b471513888c5","control_id":"H-EXP-010","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["exporter"],"objective":"Verify conditions for concessional rate supplies to merchant exporters (and procurement by the company as merchant exporter) are satisfied.","law_refs":["NOTIF-40-2017-CTR","IGST-ACT-S16"],"required_data":["sales_register","purchase_register","shipping_bills"],"procedure":"1. Identify concessional-rate supplies/purchases.\\n2. Verify export within 90 days, EPC registration, direct movement to port/registered warehouse, and documentation trail (SB copy, EGM).\\n3. Identify cases where export not evidenced.","automation":null,"expected_result":"All conditions satisfied.","exception_conditions":"Export beyond 90 days; goods moved to merchant''s own premises.","risk_level":"medium","exposure_basis":"Differential tax (normal rate minus concessional rate) + interest u/s 50(1).","evidence_required":["Merchant export documentation"],"corrective_action":"Pay differential tax with interest for non-compliant cases; enforce documentation SOP.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.558361+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"fec007e2-478a-490c-93b0-b8c36f58c785","control_id":"H-EXP-011","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["exporter"],"objective":"Ensure corrections to export data are carried out in both customs (Section 149) and GST (Table 9A) systems consistently.","law_refs":["CUSTOMS-ACT-S149","CGST-ACT-S37","CGST-RULE-96"],"required_data":["shipping_bills","gstr1"],"procedure":"1. List all shipping bill amendments and GSTR-1 Table 9A amendments.\\n2. Match them and identify one-sided corrections.\\n3. Verify time limits for GSTR-1 amendments.","automation":null,"expected_result":"Consistent amendments.","exception_conditions":"SB amended but 6A not; 9A amendments without SB support.","risk_level":"low","exposure_basis":"Refund delays; data mismatches leading to queries.","evidence_required":["Amendment logs"],"corrective_action":"Coordinate customs broker and GST teams for joint corrections.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.561942+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"e1919526-0d5f-4e19-a9ae-ea9dbc4afaa2","control_id":"I-SEZ-001","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["sez_supplier"],"objective":"Ensure supplies to SEZ are treated as inter-State zero-rated supplies under LUT or with IGST, supported by SEZ endorsement for authorised operations.","law_refs":["IGST-ACT-S7-5","IGST-ACT-S16","CGST-RULE-89","CGST-RULE-96A"],"required_data":["sales_register","gstr1","sez_endorsements","lut"],"procedure":"1. Identify customers that are SEZ units/developers from customer master and GSTIN status.\\n2. Verify invoices: IGST charged (WP) or LUT declaration (WOP); no CGST/SGST.\\n3. Obtain endorsements by SEZ authorised officer confirming receipt for authorised operations.\\n4. Verify reporting in GSTR-1 SEZWP/SEZWOP tables.","automation":null,"expected_result":"All SEZ supplies zero-rated with endorsements.","exception_conditions":"CGST/SGST charged to SEZ; endorsement missing; supply for non-authorised operations.","risk_level":"high","exposure_basis":"Without endorsement, refund denied and zero-rating challenged → IGST + interest u/s 50(1).","evidence_required":["SEZ customer list","Endorsed invoices","GSTR-1 SEZ tables"],"corrective_action":"Obtain endorsements, correct tax treatment, and add SEZ flag in customer master.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.567353+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"308ea791-d408-45c3-94ab-40506fd0a0a2","control_id":"I-SEZ-002","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["sez_supplier"],"objective":"Ensure refund claims for SEZ supplies are filed within two years with endorsed invoices and correct computation.","law_refs":["CGST-RULE-89","CGST-ACT-S54"],"required_data":["refunds","sez_endorsements","sales_register"],"procedure":"1. List SEZ supplies by month and refunds claimed.\\n2. Verify endorsement for each invoice included in claims.\\n3. Check limitation dates for unclaimed periods.","automation":null,"expected_result":"Timely and fully supported refunds.","exception_conditions":"Unclaimed periods near limitation; claims without endorsements.","risk_level":"medium","exposure_basis":"Lost refund; working capital cost.","evidence_required":["Refund files","Endorsement copies"],"corrective_action":"File pending claims and track endorsements monthly.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.572894+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"9a7a5533-440d-40c1-836d-50b7c8e6501f","control_id":"I-SEZ-003","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["importer","sez_supplier"],"objective":"Ensure transfers of title in warehoused goods before home clearance are treated as non-supply and that related ITC and reporting are aligned.","law_refs":["CGST-ACT-SCH3-8A","CGST-ACT-S17-2","CGST-RULE-42"],"required_data":["sales_register","bills_of_entry","gstr1","trial_balance"],"procedure":"1. Identify sales of goods while stored in FTWZ/bonded warehouse (high-sea/in-bond sales).\\n2. Confirm no GST charged and that the buyer files the into-bond/ex-bond BOE.\\n3. Report value as non-GST supply in GSTR-3B/GSTR-9 as applicable and include in Rule 42 exempt turnover as required by law (value of Schedule III para 8(a) supplies is specifically considered for reversal).\\n4. Verify ITC reversal on common inputs.","automation":null,"expected_result":"Correct non-supply treatment with consistent ITC reversal.","exception_conditions":"GST charged on warehoused sales; ITC reversal ignored.","risk_level":"medium","exposure_basis":"ITC reversal + interest; refund issues for GST wrongly charged (unjust enrichment).","evidence_required":["Warehoused sale documents","Ex-bond BOEs"],"corrective_action":"Adjust reporting, reverse ITC, and train sales on warehoused sale documentation.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.579078+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"fdeb96ba-5d4a-4fab-acf2-ca55690cbcf3","control_id":"I-SEZ-004","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["importer","sez_supplier"],"objective":"Ensure ITC is claimed only on IGST actually paid on bills of entry for clearance from FTWZ to DTA, and not on into-FTWZ or nil-duty BOEs.","law_refs":["CUSTOMS-TARIFF-S3-7","CGST-RULE-36-1","CGST-ACT-S16-1"],"required_data":["bills_of_entry","purchase_register","gstr2b","electronic_credit_ledger"],"procedure":"1. Classify BOEs by type (home consumption, into-bond/warehousing, ex-bond, SEZ/FTWZ DTA clearance).\\n2. Flag ITC claimed on BOEs where IGST paid is nil or where IGST is shown as bonded/ foregone.\\n3. Verify the importer name/GSTIN on BOE is the claimant.\\n4. Match ITC claimed with IGST on BOE and IMPG/IMPGSEZ in GSTR-2B.","automation":{"key": "BOE_ITC_FTWZ", "engine": "check"},"expected_result":"ITC equals IGST paid on eligible BOEs in the claimant''s name.","exception_conditions":"ITC on nil-duty or into-FTWZ BOEs; ITC claimed on BOE of FTWZ unit/other importer.","risk_level":"critical","exposure_basis":"Ineligible/excess ITC to be reversed + interest u/s 50(3) @ 18% p.a. only to the extent the credit was utilised (Rule 88B); penalty exposure u/s 73/74/74A.","evidence_required":["BOE classification","ITC mapping"],"corrective_action":"Reverse ineligible ITC with interest and implement BOE-type based ITC rules.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.589997+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"1d4e0fca-98b9-4817-bb6c-b91a5e155031","control_id":"I-SEZ-005","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["exporter","manufacturer"],"objective":"Verify deemed export supplies meet Notification 48/2017-CT conditions and refund claims are correctly made by supplier or recipient.","law_refs":["CGST-ACT-S147","NOTIF-48-2017-CT","CGST-RULE-89"],"required_data":["sales_register","refunds","purchase_register"],"procedure":"1. Identify supplies against Advance Authorisation/EPCG and to EOUs.\\n2. Verify documentation (authorisation endorsements, recipient declarations, prior intimation as applicable).\\n3. Verify tax charged and refund claims, ensuring recipient has not availed ITC where supplier claims refund.","automation":null,"expected_result":"Compliant deemed export transactions with correct refund route.","exception_conditions":"Missing documentation; double benefit.","risk_level":"medium","exposure_basis":"Refund rejection or recovery + interest.","evidence_required":["Deemed export documentation"],"corrective_action":"Complete documentation and coordinate refund claims with counterparties.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.593829+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"2409c0f7-91c6-4620-8b96-5299c8f66389","control_id":"I-SEZ-006","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["sez_supplier"],"objective":"Ensure services supplied to SEZ units (including hotel, catering, events, maintenance at SEZ premises) are treated correctly as zero-rated where for authorised operations.","law_refs":["IGST-ACT-S7-5","IGST-ACT-S16","IGST-ACT-S12"],"required_data":["sales_register","gstr1","sez_endorsements","customer_master"],"procedure":"1. Identify service invoices to SEZ GSTINs.\\n2. Verify zero-rating and authorised operations list from SEZ unit.\\n3. Verify IGST (not CGST/SGST) where supplied with payment of tax.","automation":null,"expected_result":"Correct zero-rated treatment.","exception_conditions":"CGST/SGST charged on services to SEZ; no authorised operations evidence.","risk_level":"low","exposure_basis":"Short-paid output tax + interest u/s 50(1) @ 18% p.a. from the due date of the GSTR-3B of the original period to date of payment; penalty u/s 73/74 (periods up to FY 2023-24) or u/s 74A (FY 2024-25 onwards) if raised in proceedings.","evidence_required":["SEZ service invoices","Authorised operations list"],"corrective_action":"Correct invoices and obtain endorsements.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.596985+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"b582ef84-e97d-4d69-9d4e-b24cd20a89ad","control_id":"J-IMP-001","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["importer"],"objective":"Ensure ITC on imports is claimed on BOEs reflected in GSTR-2B and identify BOEs missing from 2B.","law_refs":["CGST-RULE-36-1","CUSTOMS-TARIFF-S3-7","CGST-ACT-S16-1","CGST-ACT-S16-4"],"required_data":["bills_of_entry","gstr2b","gstr3b","purchase_register"],"procedure":"1. Download BOEs from ICEGATE for the importer''s IEC/GSTIN.\\n2. Match BOE number/date/IGST with GSTR-2B IMPG/IMPGSEZ sections.\\n3. Identify BOEs not in 2B (GSTIN not mentioned on BOE, amendment pending) and ITC claimed on them.\\n4. Track claims against Section 16(4) time limit.","automation":{"key": "BOE_NOT_IN_2B_IMPG", "engine": "check"},"expected_result":"All import ITC supported by 2B; missing BOEs resolved.","exception_conditions":"BOE with wrong GSTIN; ITC claimed without 2B reflection; BOE IGST unclaimed.","risk_level":"high","exposure_basis":"Ineligible/excess ITC to be reversed + interest u/s 50(3) @ 18% p.a. only to the extent the credit was utilised (Rule 88B); penalty exposure u/s 73/74/74A. Unclaimed import IGST is a lost-credit opportunity.","evidence_required":["BOE vs 2B match","ICEGATE BOE data"],"corrective_action":"Amend BOE GSTIN through customs, claim missed ITC within time, reverse unsupported claims.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.60283+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"3ef54cf6-ec19-4635-9bd7-cae9d5bdef65","control_id":"J-IMP-002","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["importer"],"objective":"Reconcile imports recorded in books with BOEs for value, duty and IGST to detect unrecorded imports or mis-posted duties.","law_refs":["CUSTOMS-ACT-S46","CUSTOMS-ACT-S14","CUSTOMS-TARIFF-S3-7"],"required_data":["bills_of_entry","purchase_register","general_ledger"],"procedure":"1. Extract import purchase entries and customs duty ledgers.\\n2. Match each BOE with the purchase entry (invoice, assessable value, BCD, SWS, IGST).\\n3. Identify BOEs not in books and books entries without BOE.\\n4. Verify customs duty posted to inventory cost/expense and IGST to ITC.","automation":{"type": "IMPORT_EXPORT", "engine": "recon"},"expected_result":"All BOEs accounted with correct duty and IGST bifurcation.","exception_conditions":"BOEs missing in books; IGST expensed; BCD claimed as ITC.","risk_level":"medium","exposure_basis":"Lost ITC or ineligible ITC (BCD) + interest; inventory valuation errors.","evidence_required":["Import reconciliation"],"corrective_action":"Correct postings and claim/reverse ITC accordingly.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.606682+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"b914e73d-1d78-4741-b3bc-1019cbfa2017","control_id":"J-IMP-003","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["importer"],"objective":"Prevent ITC on BOEs where no IGST was actually paid (into-bond, FTWZ entry, exemption/EOU, MOOWR deferment).","law_refs":["CUSTOMS-TARIFF-S3-7","CGST-RULE-36-1","CUSTOMS-ACT-S65"],"required_data":["bills_of_entry","electronic_credit_ledger","purchase_register"],"procedure":"1. Filter BOEs with IGST paid = 0 or BOE type warehousing/into-bond.\\n2. Match ITC claimed against these BOEs.\\n3. Confirm ITC claimed only on ex-bond BOEs where IGST was paid.","automation":{"key": "BOE_ITC_FTWZ", "engine": "check"},"expected_result":"No ITC on nil-duty BOEs.","exception_conditions":"ITC on into-bond/FTWZ BOEs; ITC on exempted imports.","risk_level":"critical","exposure_basis":"Ineligible/excess ITC to be reversed + interest u/s 50(3) @ 18% p.a. only to the extent the credit was utilised (Rule 88B); penalty exposure u/s 73/74/74A.","evidence_required":["BOE type analysis"],"corrective_action":"Reverse ITC with interest and add BOE type checks.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.609652+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"fa588bcc-af78-44d4-800b-35f30e065676","control_id":"J-IMP-004","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["importer"],"objective":"Ensure duties paid under protest are documented as such and tracked so that refund rights are protected and the GST ITC on associated IGST is appropriately handled.","law_refs":["CUSTOMS-ACT-S27","CUSTOMS-ACT-S28","CUSTOMS-ACT-S17"],"required_data":["bills_of_entry","general_ledger","challans"],"procedure":"1. Identify duty payments under protest (letters of protest, re-assessment disputes).\\n2. Verify protest letters were filed contemporaneously and acknowledged.\\n3. Track appeals and outcomes; compute refund claims due upon favourable orders.\\n4. Ensure accounting treatment (recoverable vs expensed) and disclosure as contingent asset/liability.","automation":null,"expected_result":"Protest payments documented with refund tracking.","exception_conditions":"Protest not recorded; refund claims not filed after favourable orders.","risk_level":"medium","exposure_basis":"Loss of refund if protest not documented (one-year limitation applies); contingent liabilities for disputes.","evidence_required":["Protest letters","Appeal status"],"corrective_action":"Maintain a protest register and file refunds promptly after final orders.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.612509+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"c5ee39ff-c203-4b4c-b6d2-b69b05b2bca5","control_id":"J-IMP-005","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["importer"],"objective":"Track provisionally assessed BOEs, differential duty/IGST on finalisation and corresponding ITC.","law_refs":["CUSTOMS-ACT-S18","CUSTOMS-ACT-S28AA","CGST-RULE-36-1"],"required_data":["bills_of_entry","challans","general_ledger"],"procedure":"1. List BOEs under provisional assessment with bonds/securities.\\n2. Track finalisation status and differential duty or refund.\\n3. Ensure differential IGST paid is claimed as ITC on the appropriate document.","automation":null,"expected_result":"Finalisation tracked; ITC on differential IGST claimed.","exception_conditions":"Long-pending provisional assessments; ITC on differential IGST missed.","risk_level":"low","exposure_basis":"Differential duty + interest u/s 18/28AA; lost ITC opportunity.","evidence_required":["Provisional assessment register"],"corrective_action":"Follow up finalisation and claim ITC.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.615688+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"ea8b087b-dbaf-4e64-b14f-7dc2c73bc971","control_id":"J-IMP-006","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["importer","related_party"],"objective":"Ensure related-party import values are accepted by customs and consistent with transfer pricing adjustments, including impact on IGST.","law_refs":["CUSTOMS-ACT-S14","CUSTOMS-ACT-S17","CUSTOMS-ACT-S28"],"required_data":["bills_of_entry","general_ledger","journal_vouchers"],"procedure":"1. Identify related-party suppliers and related import volumes.\\n2. Review customs valuation findings/orders and any loading.\\n3. Identify transfer pricing true-ups (year-end adjustments) and assess customs/IGST consequences.\\n4. Assess royalties/licence fees related to imported goods for inclusion in value.","automation":null,"expected_result":"Related-party values accepted with TP adjustments evaluated.","exception_conditions":"TP upward adjustments without customs evaluation; royalties not added.","risk_level":"medium","exposure_basis":"Differential duty + IGST + interest u/s 28AA; penalties.","evidence_required":["Valuation orders","TP documentation"],"corrective_action":"Evaluate voluntary payment of differential duty and align TP with customs.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.618911+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"3ff62b32-d592-44c9-8b0a-9860ebf56f00","control_id":"J-IMP-007","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["importer"],"objective":"Ensure only IGST (and compensation cess where applicable) on imports is taken as ITC while BCD and SWS are capitalised/expensed.","law_refs":["CUSTOMS-TARIFF-S3-7","CGST-ACT-S16-1"],"required_data":["bills_of_entry","general_ledger","electronic_credit_ledger"],"procedure":"1. Map duty components per BOE to GL postings.\\n2. Identify BCD/SWS posted to GST input accounts.\\n3. Verify IGST posted to GST input matches BOE IGST.","automation":null,"expected_result":"Correct segregation.","exception_conditions":"BCD/SWS posted as ITC; IGST capitalised.","risk_level":"medium","exposure_basis":"Ineligible/excess ITC to be reversed + interest u/s 50(3) @ 18% p.a. only to the extent the credit was utilised (Rule 88B); penalty exposure u/s 73/74/74A.","evidence_required":["Duty posting analysis"],"corrective_action":"Correct postings and ITC claims.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.623142+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"f6783d1b-c7ad-4076-ac76-35d262e4df36","control_id":"J-IMP-008","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["importer","manufacturer"],"objective":"Ensure MOOWR operations comply with customs conditions and GST treatment on clearances is correct.","law_refs":["CUSTOMS-ACT-S65","CGST-ACT-SCH3-8A","CUSTOMS-TARIFF-S3-7"],"required_data":["bills_of_entry","stock_register","sales_register","shipping_bills"],"procedure":"1. Obtain MOOWR licence and permission.\\n2. Reconcile warehoused imported inputs and capital goods with consumption and clearances.\\n3. Verify duty payment on DTA clearances and export documentation for exports.\\n4. Verify GST on supplies of finished goods cleared to DTA.","automation":null,"expected_result":"Inventory reconciled; duties paid on DTA clearances.","exception_conditions":"Unaccounted warehoused goods; clearances without duty.","risk_level":"medium","exposure_basis":"Customs duty + interest; GST on supplies.","evidence_required":["MOOWR registers","Clearance documentation"],"corrective_action":"Reconcile, pay duty with interest where due, and strengthen warehouse accounting.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.62654+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"691167c8-2fab-4867-8135-f01663bc56c0","control_id":"K-JW-001","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["job_work"],"objective":"Ensure ITC-04 is filed for the prescribed periods and reconciles with challans and stock lying with job workers.","law_refs":["CGST-ACT-S143","CGST-RULE-45"],"required_data":["itc04","stock_register","eway_bill_register"],"procedure":"1. Obtain ITC-04 filings and challan registers for the period.\\n2. Reconcile quantities sent, received back, supplied directly from job worker premises and closing stock at job workers.\\n3. Match challans with EWBs.\\n4. Verify filing frequency (half-yearly/annual by AATO) and timeliness.","automation":null,"expected_result":"ITC-04 complete, timely and reconciled.","exception_conditions":"Unfiled ITC-04; unreconciled quantities; challans without EWB.","risk_level":"medium","exposure_basis":"Deemed supply exposure for unreturned goods (see K-JW-002); general penalty u/s 125.","evidence_required":["ITC-04 acknowledgements","Job worker stock reconciliation"],"corrective_action":"File pending ITC-04 and reconcile with job workers quarterly.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.629846+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"43538296-ed9a-4bcb-b0d9-dfd13d3ba3cd","control_id":"K-JW-002","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["job_work"],"objective":"Identify inputs not returned within one year and capital goods within three years from job workers, which are deemed supplied on the date of dispatch.","law_refs":["CGST-ACT-S143","CGST-ACT-S19","CGST-ACT-S50-1"],"required_data":["itc04","stock_register"],"procedure":"1. Age challan-wise outstanding quantities at job workers.\\n2. Flag inputs beyond one year and capital goods beyond three years (excluding moulds, dies, jigs, fixtures, tools).\\n3. Verify invoice raised and tax paid with interest from the original dispatch date.\\n4. Verify any extension obtained.","automation":null,"expected_result":"No overdue goods without tax compliance.","exception_conditions":"Overdue goods at job worker without deemed supply invoice.","risk_level":"high","exposure_basis":"Short-paid output tax + interest u/s 50(1) @ 18% p.a. from the due date of the GSTR-3B of the original period to date of payment; penalty u/s 73/74 (periods up to FY 2023-24) or u/s 74A (FY 2024-25 onwards) if raised in proceedings. Interest runs from the original date of dispatch.","evidence_required":["Challan ageing","Deemed supply invoices"],"corrective_action":"Raise invoices for deemed supply with tax and interest and retrieve/reconcile goods.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.632659+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"0fab4fb2-5c1f-4f45-88fb-8bfb724f88a8","control_id":"K-JW-003","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["job_work"],"objective":"Ensure all job work movements are accompanied by challans with prescribed particulars.","law_refs":["CGST-RULE-55","CGST-RULE-45"],"required_data":["stock_register","eway_bill_register","itc04"],"procedure":"1. Sample job work dispatches and receipts.\\n2. Verify challans contain prescribed particulars and serial numbers.\\n3. Verify EWB coverage for inter-State movements and above-threshold intra-State movements.","automation":{"key": "EWB_MISSING", "engine": "check"},"expected_result":"Challans and EWBs for all movements.","exception_conditions":"Movements on informal gate passes.","risk_level":"low","exposure_basis":"Detention/penalty in transit; deemed supply challenge.","evidence_required":["Challan samples"],"corrective_action":"System-generate challans with EWB integration.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.63521+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"1f70176d-ee44-4f47-9dd4-16d147fe84b7","control_id":"K-JW-004","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["job_work","manufacturer"],"objective":"Verify GST rate on job work services received/supplied and treatment of waste and scrap generated at job worker premises.","law_refs":["NOTIF-11-2017-CTR","CGST-ACT-S143","CGST-ACT-S16-1"],"required_data":["purchase_register","sales_register","stock_register"],"procedure":"1. Identify job work service invoices and applicable rate entries (based on goods and ownership).\\n2. Verify rate charged against notification entries.\\n3. Trace waste/scrap at job worker: who supplied, tax paid, and stock accounting.","automation":{"key": "WRONG_RATE", "engine": "check"},"expected_result":"Correct rates and scrap compliance.","exception_conditions":"Wrong rate on job work; scrap sold by job worker without tax.","risk_level":"medium","exposure_basis":"Short-paid output tax + interest u/s 50(1) @ 18% p.a. from the due date of the GSTR-3B of the original period to date of payment; penalty u/s 73/74 (periods up to FY 2023-24) or u/s 74A (FY 2024-25 onwards) if raised in proceedings.","evidence_required":["Job work invoices","Scrap records"],"corrective_action":"Correct rate application and document scrap treatment.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.638854+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"6cc5c67c-fe5a-4db5-9a17-38b08d76f3fd","control_id":"K-MFG-005","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["manufacturer"],"objective":"Ensure ITC is reversed on inputs/finished goods written off, destroyed, lost or stolen, including inventory shortages identified on physical verification.","law_refs":["CGST-ACT-S17-5","CGST-ACT-S16-1"],"required_data":["stock_register","trial_balance","general_ledger","journal_vouchers"],"procedure":"1. Extract inventory write-off, obsolescence, physical verification shortage and insurance claim ledgers.\\n2. Distinguish normal process loss (no reversal) from write-off/destruction (reversal).\\n3. Compute ITC attributable (input-level for finished goods) and verify reversal in GSTR-3B.","automation":null,"expected_result":"ITC reversed for write-offs and losses.","exception_conditions":"Write-offs booked without ITC reversal; provisions vs actual write-off confusion.","risk_level":"medium","exposure_basis":"Ineligible/excess ITC to be reversed + interest u/s 50(3) @ 18% p.a. only to the extent the credit was utilised (Rule 88B); penalty exposure u/s 73/74/74A.","evidence_required":["Write-off approvals","ITC reversal computation"],"corrective_action":"Reverse ITC with interest where utilised and link inventory write-off workflow to GST reversal.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.641286+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"363bf5c8-ab0b-42aa-bbc8-51adbb161297","control_id":"K-MFG-006","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["manufacturer"],"objective":"Identify and claim refunds of accumulated ITC due to inverted rate structure within limitation and in line with Rule 89(5).","law_refs":["CGST-ACT-S54","CGST-RULE-89"],"required_data":["gstr3b","purchase_register","sales_register","refunds"],"procedure":"1. Compare input and output rates by product line.\\n2. Compute refund under Rule 89(5) (inputs only, excluding input services and capital goods).\\n3. Check exclusions notified for certain goods.\\n4. Track two-year limitation from the due date of the return for the period.","automation":null,"expected_result":"Eligible refunds claimed timely.","exception_conditions":"Accumulated credit not claimed; computation including services.","risk_level":"low","exposure_basis":"Lost refund (opportunity); recovery for excess refunds + interest.","evidence_required":["Inverted duty computation"],"corrective_action":"File refunds and monitor accumulation.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.643937+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"dfe1b5f6-0dd1-479d-8650-8ae162049760","control_id":"L-FA-001","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure tax is paid on disposal of capital goods at the higher of tax on transaction value or ITC taken less 5 percentage points per quarter.","law_refs":["CGST-ACT-S18-6","CGST-RULE-44-6","CGST-ACT-SCH1-1"],"required_data":["fixed_asset_register","sales_register","gstr1","general_ledger"],"procedure":"1. Extract asset deletions from the fixed asset register with dates, sale proceeds and original ITC.\\n2. Compute ITC attributable to remaining life (ITC less 5 percentage points per quarter or part since invoice date).\\n3. Compute tax on transaction value; determine the higher amount.\\n4. Verify invoice issued and amount paid; for transfers without consideration, check Schedule I para 1.","automation":{"key": "FA_DISPOSAL", "engine": "check"},"expected_result":"Tax paid at the higher of the two amounts for every disposal.","exception_conditions":"Asset sales without invoice; tax paid only on transaction value when ITC-based amount is higher; inter-unit asset transfers untaxed.","risk_level":"high","exposure_basis":"Short-paid output tax + interest u/s 50(1) @ 18% p.a. from the due date of the GSTR-3B of the original period to date of payment; penalty u/s 73/74 (periods up to FY 2023-24) or u/s 74A (FY 2024-25 onwards) if raised in proceedings.","evidence_required":["Asset disposal listing","Section 18(6) computations","Invoices"],"corrective_action":"Pay differential with interest and integrate disposal workflow with GST computation.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.647674+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"26da395a-9197-410b-a55d-bdbc5559c6ef","control_id":"L-FA-002","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure capital goods sold as scrap are taxed under Section 18(6) and capital goods written off/destroyed are evaluated for ITC reversal.","law_refs":["CGST-ACT-S18-6","CGST-RULE-44-6","CGST-ACT-S17-5"],"required_data":["fixed_asset_register","sales_register","general_ledger"],"procedure":"1. Identify assets scrapped or written off during the period.\\n2. Trace scrap sale invoices and tax paid; apply Section 18(6) computation (with transaction-value option for refractory bricks, moulds and dies, jigs and fixtures sold as scrap).\\n3. For assets written off without sale, assess ITC reversal position.","automation":{"key": "FA_DISPOSAL", "engine": "check"},"expected_result":"Scrap sales taxed correctly; write-offs evaluated.","exception_conditions":"Scrap sales booked to miscellaneous income without tax.","risk_level":"medium","exposure_basis":"Short-paid output tax + interest u/s 50(1) @ 18% p.a. from the due date of the GSTR-3B of the original period to date of payment; penalty u/s 73/74 (periods up to FY 2023-24) or u/s 74A (FY 2024-25 onwards) if raised in proceedings.","evidence_required":["Scrap sale invoices","Asset write-off approvals"],"corrective_action":"Pay tax with interest and document position on write-offs.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.650989+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"47e6d95c-ecc8-4f1c-b875-87daefd9bda3","control_id":"L-FA-003","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure ITC is not claimed on capital goods blocked under Section 17(5), particularly civil works, buildings and passenger vehicles.","law_refs":["CGST-ACT-S17-5","JUDG-SAFARI-RETREATS-2024"],"required_data":["fixed_asset_register","purchase_register","general_ledger"],"procedure":"1. Extract capitalisations with ITC claimed by asset class.\\n2. Flag buildings, civil works, furniture fixed to building, and motor vehicles.\\n3. Evaluate plant and machinery exceptions (foundations and structural supports for machinery) and functionality arguments considering the retrospective amendment.\\n4. Verify CWIP ITC claims.","automation":{"key": "BLOCKED_ITC_17_5", "engine": "check"},"expected_result":"No blocked ITC on capital goods.","exception_conditions":"ITC on building construction, passenger cars, or CWIP civil works.","risk_level":"high","exposure_basis":"Ineligible/excess ITC to be reversed + interest u/s 50(3) @ 18% p.a. only to the extent the credit was utilised (Rule 88B); penalty exposure u/s 73/74/74A.","evidence_required":["Capitalisation listing with ITC","Technical notes on plant and machinery"],"corrective_action":"Reverse blocked ITC with interest and set asset-class ITC rules.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.654796+00:00"}') on conflict do nothing;
