insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"1734458a-ad19-43df-ad3b-d839a94eaed7","control_id":"L-FA-006","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":["multi_gstin","job_work"],"objective":"Ensure capital goods moved to job workers are returned within three years and inter-GSTIN transfers are taxed as supplies between distinct persons.","law_refs":["CGST-ACT-S19","CGST-ACT-SCH1-2","CGST-ACT-S18-6"],"required_data":["fixed_asset_register","itc04","sales_register","eway_bill_register"],"procedure":"1. Identify asset location changes and transfers in the FAR.\\n2. Verify invoices for transfers across GSTINs (valued per Rule 28 and subject to Section 18(6) comparison as applicable).\\n3. Verify challans and ITC-04 for capital goods at job workers and return within three years.","automation":null,"expected_result":"Compliant movements and transfers.","exception_conditions":"Inter-State asset transfers on challan; capital goods at job workers beyond three years.","risk_level":"medium","exposure_basis":"Short-paid output tax + interest u/s 50(1) @ 18% p.a. from the due date of the GSTR-3B of the original period to date of payment; penalty u/s 73/74 (periods up to FY 2023-24) or u/s 74A (FY 2024-25 onwards) if raised in proceedings.","evidence_required":["Asset movement records"],"corrective_action":"Invoice transfers and regularise job work capital goods.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.669304+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"da221a23-b56d-4faf-a077-b8a5fb52f3da","control_id":"M-LED-001","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Identify idle or misallocated balances in the electronic cash ledger and optimise through utilisation, PMT-09 transfer or refund.","law_refs":["CGST-RULE-87","CGST-ACT-S49","CGST-ACT-S54"],"required_data":["electronic_cash_ledger","challans","gstr3b"],"procedure":"1. Download electronic cash ledger balances by major/minor head for each GSTIN.\\n2. Identify balances idle for more than a defined period and balances in wrong heads (e.g., interest/penalty heads, wrong State tax head).\\n3. Evaluate PMT-09 transfers between heads/distinct GSTINs (where permitted) or refund through RFD-01.\\n4. Check for challans paid but not credited (CIN issues).","automation":{"key": "CASH_LEDGER_IDLE", "engine": "check"},"expected_result":"Minimal idle balances; misallocations corrected.","exception_conditions":"Large idle balances; balances in interest/penalty heads not utilisable; unclaimed excess.","risk_level":"low","exposure_basis":"Working capital blocked (H bucket: cash transfer/refund opportunity).","evidence_required":["Cash ledger extract","PMT-09 / refund records"],"corrective_action":"Transfer via PMT-09, utilise in next return, or claim refund.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.672361+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"eef95d8c-61fd-40bc-aae0-543b7cabb3ea","control_id":"M-LED-002","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Reconcile GST input ledgers in books with the electronic credit ledger to detect negative balances, unreconciled differences and unbooked reversals.","law_refs":["CGST-RULE-86","CGST-ACT-S49","CGST-ACT-S35"],"required_data":["tax_ledgers","electronic_credit_ledger","trial_balance","gstr3b"],"procedure":"1. Extract head-wise GST input and output ledgers from books by GSTIN and month.\\n2. Compare closing balances with the electronic credit ledger.\\n3. Flag negative input ledger balances (indicating excess utilisation or wrong postings) and differences beyond tolerance.\\n4. Analyse root causes: reversals not booked, ITC claimed but not in books, set-off entries incorrect.","automation":{"key": "NEGATIVE_ITC_BALANCE", "engine": "check"},"expected_result":"Book balances reconcile with the electronic credit ledger.","exception_conditions":"Negative input ledger balances; persistent unexplained differences.","risk_level":"medium","exposure_basis":"Indicator of excess ITC claims or unrecorded liabilities; quantified via C-ITC-001.","evidence_required":["Ledger reconciliation"],"corrective_action":"Rectify postings and align monthly set-off journals with GSTR-3B.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.676149+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"afeaa034-6624-40c6-8e2f-6af544b512f8","control_id":"M-LED-003","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Verify that ITC is utilised in the prescribed order and that cross-utilisation of CGST and SGST credit does not occur.","law_refs":["CGST-ACT-S49A","CGST-RULE-88A","CGST-ACT-S49"],"required_data":["gstr3b","electronic_credit_ledger","electronic_liability_register"],"procedure":"1. Extract GSTR-3B Table 6.1 set-off details for each month.\\n2. Verify IGST credit used first for IGST and then CGST/SGST.\\n3. Check no CGST credit used for SGST liability and vice versa.","automation":null,"expected_result":"Utilisation in prescribed order.","exception_conditions":"Manual utilisation errors leading to excess cash payment in one head and credit build-up in another.","risk_level":"low","exposure_basis":"Cash flow inefficiency; head-wise imbalance across Centre/State.","evidence_required":["Set-off tables"],"corrective_action":"Use system-recommended utilisation and monitor head-wise balances.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.679058+00:00"}') on conflict do nothing;
