insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"dadbfd52-5444-4409-819b-c1b4a16bb4e4","control_id":"M-LED-005","version":1,"effective_from":"2019-12-26","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Identify any blocking of the electronic credit ledger and ensure timely representation and tracking of the one-year limit.","law_refs":["CGST-RULE-86A","CGST-ACT-S16-2"],"required_data":["electronic_credit_ledger"],"procedure":"1. Review the credit ledger for negative blocked balances and portal notices.\\n2. Obtain reasons for blocking and evaluate documentary defence (receipt of goods, supplier existence, payment).\\n3. Track date of blocking and statutory one-year lapse.","automation":null,"expected_result":"No blocking, or blocking contested with documentation.","exception_conditions":"Blocked credit unaddressed; blocking beyond one year not auto-released.","risk_level":"high","exposure_basis":"Blocked ITC (working capital) and potential demand of ITC with interest and penalty.","evidence_required":["Blocking notices","Representations"],"corrective_action":"File representation with evidence and follow up for unblocking.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.684819+00:00"}') on conflict do nothing;
