insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"0c16bf54-a18d-4368-8cbd-02e2a0289f75","control_id":"N-AR-001","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Ensure the annual return correctly reflects outward supplies, ITC and tax paid, reconciling with books and periodic returns.","law_refs":["CGST-ACT-S44","CGST-RULE-80"],"required_data":["gstr9","gstr1","gstr3b","trial_balance"],"procedure":"1. Compare GSTR-9 Table 4/5 with GSTR-1 and books.\\n2. Compare Table 6 ITC with GSTR-3B and books.\\n3. Compare Table 9 tax paid with GSTR-3B and DRC-03.\\n4. Identify unexplained differences and verify additional liability paid via DRC-03.","automation":{"type": "GSTR1_GSTR3B", "engine": "recon"},"expected_result":"GSTR-9 reconciles with source data.","exception_conditions":"Differences without explanation; additional liability not paid.","risk_level":"medium","exposure_basis":"Short-paid output tax + interest u/s 50(1) @ 18% p.a. from the due date of the GSTR-3B of the original period to date of payment; penalty u/s 73/74 (periods up to FY 2023-24) or u/s 74A (FY 2024-25 onwards) if raised in proceedings.","evidence_required":["GSTR-9 reconciliation"],"corrective_action":"Pay additional liability and maintain reconciliation workpapers.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.689658+00:00"}') on conflict do nothing;
