insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"808273e6-8f15-4d0e-a009-0e844160b928","control_id":"O-INT-001","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Recompute interest on tax paid late (net cash basis for delayed returns) and verify payment.","law_refs":["CGST-ACT-S50-1","CGST-ACT-S39"],"required_data":["gstr3b","electronic_cash_ledger","challans"],"procedure":"1. Compile GSTR-3B filing dates and cash debits by period.\\n2. Compute interest @ 18% p.a. on cash portion for days of delay (net tax liability proviso).\\n3. Compute interest on liabilities of earlier periods paid later (on gross basis where applicable).\\n4. Compare with interest paid.","automation":null,"expected_result":"Interest fully paid.","exception_conditions":"Interest unpaid or short-paid.","risk_level":"medium","exposure_basis":"Unpaid interest u/s 50(1) recoverable directly.","evidence_required":["Interest computation"],"corrective_action":"Pay interest through DRC-03.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.707374+00:00"}') on conflict do nothing;
insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"bd03e6ac-b30d-42d6-b715-c34bb6e14ff6","control_id":"O-INT-002","version":1,"effective_from":"2022-07-05","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Quantify interest on ITC wrongly availed and utilised, applying the Rule 88B utilisation test.","law_refs":["CGST-ACT-S50-3","CGST-RULE-88B"],"required_data":["electronic_credit_ledger","gstr3b","purchase_register"],"procedure":"1. Identify ITC reversals relating to wrongly availed credit.\\n2. Determine whether and when the electronic credit ledger balance fell below the wrongly availed amount (head-wise, considering IGST/CGST/SGST cross-utilisation).\\n3. Compute interest from date of utilisation to date of reversal @ 18% p.a.\\n4. Compare with interest paid.","automation":null,"expected_result":"Interest paid only where ITC utilised, correctly computed.","exception_conditions":"Interest not paid on utilised credit; interest overpaid where balance remained sufficient.","risk_level":"medium","exposure_basis":"Interest u/s 50(3); potential refund of interest overpaid.","evidence_required":["Daily credit ledger balances","Interest working"],"corrective_action":"Pay or claim refund of interest as applicable.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.710282+00:00"}') on conflict do nothing;
