insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"e8e21662-dec6-458e-904a-466243b71644","control_id":"O-LIM-004","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Maintain a limitation tracker for each FY under Sections 73, 74 and 74A, so that exposure and defence strategies reflect time-bar positions.","law_refs":["CGST-ACT-S73","CGST-ACT-S74","CGST-ACT-S74A"],"required_data":["gstr9","gstr3b"],"procedure":"1. For each FY, identify the due date of the annual return (and any extensions).\\n2. For FY up to 2023-24, compute last dates for SCN (Section 73: three months before the three-year order limit; Section 74: six months before the five-year order limit).\\n3. For FY 2024-25 onwards, compute notice limit under Section 74A (42 months from due date of annual return).\\n4. Map open audit observations to FYs and flag those approaching time-bar.","automation":null,"expected_result":"Tracker maintained and used in risk assessment.","exception_conditions":"Exposure quantified for time-barred years; notices received beyond limitation not challenged.","risk_level":"medium","exposure_basis":"Determines whether quantified exposures in other controls remain enforceable.","evidence_required":["Limitation tracker"],"corrective_action":"Update tracker annually and challenge time-barred notices.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.718362+00:00"}') on conflict do nothing;
